add_filter( 'woocommerce_package_rates', 'perfectpixel_hide_rate_by_variation', 10, 2 );

function perfectpixel_hide_rate_by_variation( $rates, $package ) {
	$variations = wp_parse_id_list( '{{hide_rate_variation_ids}}' );
	if ( ! $variations ) {
		return $rates;
	}
	$found = false;
	foreach ( $package['contents'] as $item ) {
		if ( in_array( (int) $item['variation_id'], $variations, true ) ) {
			$found = true;
			break;
		}
	}
	if ( ! $found ) {
		return $rates;
	}
	$targets = array_filter( array_map( 'trim', explode( ',', '{{hide_rate_for_variations}}' ) ) );
	foreach ( $rates as $rate_id => $rate ) {
		if ( in_array( $rate_id, $targets, true ) || in_array( $rate->get_method_id(), $targets, true ) ) {
			unset( $rates[ $rate_id ] );
		}
	}
	return $rates;
}
